// Plan:
// 1. Parse the input JSON array of strings.
// 2. Use a HashMap to count occurrences of each string.
// 3. Filter out strings that occur less than twice.
// 4. Sort the remaining strings lexicographically.
// 5. Convert the result back to a JSON array and return.

use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    // Step 1: Parse the input JSON array of strings.
    let strings: Vec<String> = match input {
        Value::Array(arr) => arr.into_iter().filter_map(|v| v.as_str().map(String::from)).collect(),
        _ => Vec::new(),
    };

    // Step 2: Use a HashMap to count occurrences of each string.
    use std::collections::HashMap;
    let mut counts = HashMap::new();
    for s in &strings {
        *counts.entry(s).or_insert(0) += 1;
    }

    // Step 3: Filter out strings that occur less than twice.
    let mut result: Vec<String> = counts.into_iter()
        .filter(|&(_, count)| count >= 2)
        .map(|(s, _)| s)
        .collect();

    // Step 4: Sort the remaining strings lexicographically.
    result.sort_unstable();

    // Step 5: Convert the result back to a JSON array and return.
    json!(result)
}
